import { Object3D, Group, Mesh, PlaneGeometry, Vector3 } from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    textureNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}|[number,number,number]} position
 * @property {{x:number,y:number,z:number}|[number,number,number]} rotation
 * @property {{x:number,y:number,z:number}|[number,number,number]} scale
 * @property {{imageUrl:string}} assets
 * @property {{textContent: Array<{content:string}>}} textContent
 * @property {{colors?:Object}} colors
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>import('three').Texture}} textureLoader
 * @property {{create: (opts:any)=>import('three').Texture}} fontAtlas
 * @property {{[key:string]: (obj:Object3D, params:any)=>void}} primitives
 */

/**
 * Create a billboarded sprite node with background image and MSDF text overlay.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    // Helper to apply vector values (array or object)
    const applyVector = (target, src) => {
        if (Array.isArray(src) && src.length === 3) {
            target.set(src[0], src[1], src[2]);
        } else if (src && typeof src === 'object') {
            target.set(src.x ?? 0, src.y ?? 0, src.z ?? 0);
        }
    };

    // Root container
    const root = new Group();
    applyVector(root.position, config.position ?? [0, 0, 0]);
    applyVector(root.rotation, config.rotation ?? [0, 0, 0]);
    applyVector(root.scale, config.scale ?? [1, 1, 1]);

    // --------------------------------------------------------------------
    // Background plane (sprite)
    // --------------------------------------------------------------------
    // Load background texture (atlas or single image)
    const bgTexture = ctx.textureLoader.load(config.assets?.imageUrl);

    // Atlas region – fallback to full texture if not supplied
    const atlasRegion = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
    const aspect = atlasRegion.w / atlasRegion.h;

    const planeGeom = new PlaneGeometry(aspect, 1, 1, 1);

    const bgMaterial = new MeshBasicNodeMaterial({
        map: textureNode(bgTexture),
        side: THREE.DoubleSide,
        transparent: true,
        depthWrite: false,
    });
    // UV correction for atlas region (if the texture is an atlas)
    // Here we simply rely on the caller providing a texture that already
    // matches the region; otherwise additional UV transform would be needed.

    const bgMesh = new Mesh(planeGeom, bgMaterial);
    bgMesh.renderOrder = 0;
    root.add(bgMesh);

    // --------------------------------------------------------------------
    // Text overlay (MSDF)
    // --------------------------------------------------------------------
    const textString = (config.textContent?.[0]?.content) ?? 'Journal';
    const textOpts = {
        text: textString,
        font: 'Lora',
        size: 96, // aligns with spec “headline, 96px 400”
        color: config.colors?.ink ?? '#16161d',
        // The atlas region for the text could be defined here if needed.
    };
    const textTexture = ctx.fontAtlas.createTexture(textOpts);

    const textMaterial = new MeshBasicNodeMaterial({
        map: textureNode(textTexture),
        transparent: true,
        depthTest: false,
        depthWrite: false,
    });
    const textMesh = new Mesh(planeGeom, textMaterial);
    textMesh.renderOrder = 1;
    // Slight offset to avoid Z‑fighting
    textMesh.position.set(0, 0, 0.001);
    root.add(textMesh);

    // --------------------------------------------------------------------
    // Apply cinematic primitives (if any)
    // --------------------------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // --------------------------------------------------------------------
    // Cleanup & handlers
    // --------------------------------------------------------------------
    root.userData.handlers = {};

    root.userData.cleanup = () => {
        // Dispose materials and geometry
        bgMaterial.dispose();
        textMaterial.dispose();
        planeGeom.dispose();

        // Dispose textures if they are not shared resources
        if (bgTexture && typeof bgTexture.dispose === 'function') {
            bgTexture.dispose();
        }
        if (textTexture && typeof textTexture.dispose === 'function') {
            textTexture.dispose();
        }

        // Kill any GSAP timelines that might have been attached
        gsap.globalTimeline.clear();
    };

    return root;
}
